// pg — the % wildcards live in the bound VALUE, never in the SQL text
const { rows } = await client.query(
  'SELECT id, name, price FROM products WHERE name LIKE $1',
  ['%' + q + '%'],
);
// mysql2: conn.execute('... WHERE name LIKE ?', ['%' + q + '%'])

// PDO — the % wildcards are part of the bound value, not the SQL
$stmt = $pdo->prepare(
    'SELECT id, name, price FROM products WHERE name LIKE ?'
);
$stmt->execute(['%' . $q . '%']);
$rows = $stmt->fetchAll(PDO::FETCH_ASSOC);

// JDBC — bind the pattern; the % wildcards live in the value, not the SQL
PreparedStatement ps = conn.prepareStatement(
    "SELECT id, name, price FROM products WHERE name LIKE ?");
ps.setString(1, "%" + q + "%");
ResultSet rs = ps.executeQuery();

// ADO.NET — the % wildcards are part of the bound value, not the SQL
using var cmd = new SqlCommand(
    "SELECT id, name, price FROM products WHERE name LIKE @q", conn);
cmd.Parameters.Add(new SqlParameter("@q", "%" + q + "%"));
using var reader = cmd.ExecuteReader();
